  const { result } = renderHook(() => useGameState());
  const { setCount, card } = result.current;
  const saga = {
    id: 'saga1',
    name: 'Three-Chapter Saga',
    chapters: [
      { id: 'chapter1', threshold: 1 },
      { id: 'chapter2', threshold: 2 },
      { id: 'chapter3', threshold: 3 }
    ]
  };

  // Initial state
  setCount(0);
  expect(card.triggeredChapters).toEqual([]);

  // Jump to 2
  setCount(2);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2']);

  // Jump to 3
  setCount(3);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2', 'chapter3']);

  // Jump to 4 (no new chapters)
  setCount(4);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2', 'chapter3']);
});

// Test adjustCount with chapter threshold
it('should record crossed chapters when adjusting count', () => {
  const { result } = renderHook(() => useGameState());
  const { adjustCount, card } = result.current;
  const saga = {
    id: 'saga1',
    name: 'Three-Chapter Saga',
    chapters: [
      { id: 'chapter1', threshold: 1 },
      { id: 'chapter2', threshold: 2 },
      { id: 'chapter3', threshold: 3 }
    ]
  };

  // Initial state
  adjustCount(0, 1);
  expect(card.triggeredChapters).toEqual(['chapter1']);

  // Adjust to 2
  adjustCount(1, 1);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2']);

  // Adjust to 3
  adjustCount(2, 1);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2', 'chapter3']);

  // Adjust down to 2 (should not un-trigger chapter3)
  adjustCount(3, -1);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2', 'chapter3']);

  // Adjust down to 1 (should not un-trigger chapter2)
  adjustCount(2, -1);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2', 'chapter3']);

  // Adjust down to 0 (should not un-trigger any)
  adjustCount(1, -1);
  expect(card.triggeredChapters).toEqual(['chapter1', 'chapter2', 'chapter3']);
});

